PRAGMA foreign_keys = ON;

-- Categories must exist before Snicks reference them via category_id (seed.sql normally
-- inserts these, but migrations run before the seed file, so upsert them here too).
INSERT OR IGNORE INTO snick_categories (id, name, description, color_key) VALUES
  ('cat_communication', 'Communication', 'Snicks focused on talking, listening & expressing.', 'daily'),
  ('cat_emotional', 'Emotional Connection', 'Snicks focused on empathy, vulnerability & closeness.', 'weekly'),
  ('cat_efforts', 'Efforts', 'Snicks focused on thoughtful gestures & acts of care.', 'monthly'),
  ('cat_trust', 'Trust', 'Snicks focused on honesty, reliability & security.', 'daily');

-- Remove the old placeholder demo Snicks (and their completions/verifications/xp events)
-- so the couple's journey map is driven entirely by the real dataset going forward.
DELETE FROM snick_verifications WHERE completion_id IN (SELECT id FROM snick_completions WHERE snick_id LIKE 'snk\_day%' ESCAPE '\' OR snick_id LIKE 'snk\_week%' ESCAPE '\' OR snick_id LIKE 'snk\_month%' ESCAPE '\');
DELETE FROM couple_xp_events WHERE source_id IN (SELECT id FROM snick_completions WHERE snick_id LIKE 'snk\_day%' ESCAPE '\' OR snick_id LIKE 'snk\_week%' ESCAPE '\' OR snick_id LIKE 'snk\_month%' ESCAPE '\');
DELETE FROM snick_completions WHERE snick_id LIKE 'snk\_day%' ESCAPE '\' OR snick_id LIKE 'snk\_week%' ESCAPE '\' OR snick_id LIKE 'snk\_month%' ESCAPE '\';
DELETE FROM snicks WHERE id LIKE 'snk\_day%' ESCAPE '\' OR id LIKE 'snk\_week%' ESCAPE '\' OR id LIKE 'snk\_month%' ESCAPE '\';

